-- ==========================================
-- QuizFlow Database Schema (DDL)
-- Compatible with PostgreSQL and H2.
-- 
-- For MySQL compatibility:
-- 1. Remove "CASCADE" from "DROP TABLE IF EXISTS" statements.
-- 2. Replace "GENERATED BY DEFAULT AS IDENTITY" with "AUTO_INCREMENT" for primary keys.
-- ==========================================

-- Drop tables if they exist to allow clean initialization
DROP TABLE IF EXISTS options CASCADE;
DROP TABLE IF EXISTS quiz_cards CASCADE;
DROP TABLE IF EXISTS topics CASCADE;
DROP TABLE IF EXISTS subjects CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- 1. Users Table
CREATE TABLE users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. Subjects Table (Dynamic Tabs)
CREATE TABLE subjects (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL,
    name VARCHAR(100) NOT NULL,
    color VARCHAR(7) DEFAULT '#6366f1',
    icon VARCHAR(50) DEFAULT 'database',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_subject_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_subjects_user_id ON subjects(user_id);

-- 3. Topics Table (Chapters/Units)
CREATE TABLE topics (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    subject_id BIGINT NOT NULL,
    name VARCHAR(100) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_topic_subject FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE
);
CREATE INDEX idx_topics_subject_id ON topics(subject_id);

-- 4. QuizCards Table
CREATE TABLE quiz_cards (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    topic_id BIGINT NOT NULL,
    question TEXT NOT NULL,
    code_snippet TEXT NULL,
    explanation TEXT NULL,
    mastered BOOLEAN DEFAULT FALSE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_card_topic FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
);
CREATE INDEX idx_cards_topic_id ON quiz_cards(topic_id);

-- 5. Options Table
CREATE TABLE options (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    quiz_card_id BIGINT NOT NULL,
    option_text TEXT NOT NULL,
    is_correct BOOLEAN DEFAULT FALSE NOT NULL,
    display_order INT NOT NULL DEFAULT 0,
    CONSTRAINT fk_option_card FOREIGN KEY (quiz_card_id) REFERENCES quiz_cards(id) ON DELETE CASCADE
);
CREATE INDEX idx_options_card_id ON options(quiz_card_id);

